Bash(node -e "
const cx=0.12, cy=-0.17, rz=0.3, half=0.17;
// bottom of cylinder in pivot-local, accounting for rotation.z
const bx = cx + half*Math.sin\(rz\);
const by = cy - half*Math.cos\(rz\);
console.log\('Hand endpoint \(pivot-local\):', bx.toFixed\(3\), by.toFixed\(3\), '0.000'\);
// sword grip is at y=-0.10 in sword-local, also rotated by rz=0.3
const gx_off = 0.10*Math.sin\(rz\);
const gy_off = -0.10*Math.cos\(rz\);
console.log\('Grip offset from swordGroup origin:', gx_off.toFixed\(3\), gy_off.toFixed\(3\)\);
// swordGroup.position = hand - grip_offset
const sx = bx - gx_off;
const sy = by - gy_off;
console.log\('swordGroup.position should be:', sx.toFixed\(3\), sy.toFixed\(3\)\);
")
